51→/**
52→ * @param {string} username
53→ * @param {string} reponame
54→ * @returns {Promise<import("./types").RepositoryData>}
55→ */
56→async function fetchRepo(username, reponame) {
57→  if (!username || !reponame) {
58→    throw new Error("Invalid username or reponame");
59→  }
60→
61→  let res = await retryer(fetcher, { login: username, repo: reponame });
62→
63→  const data = res.data.data;
64→
65→  if (!data.user && !data.organization) {
66→    throw new Error("Not found");
67→  }
68→
69→  const isUser = data.organization === null && data.user;
70→  const isOrg = data.user === null && data.organization;
71→
72→  if (isUser) {
73→    if (!data.user.repository || data.user.repository.isPrivate) {
74→      throw new Error("User Repository Not found");
75→    }
76→    return {
77→      ...data.user.repository,
78→      starCount: data.user.repository.stargazers.totalCount,
79→    };
80→  }
81→
82→  if (isOrg) {
