 42→/**
 43→ * @param {string} username
 44→ * @param {string[]} exclude_repo
 45→ * @returns {Promise<import("./types").TopLangData>}
 46→ */
 47→async function fetchTopLanguages(username, exclude_repo = []) {
 48→  if (!username) throw Error("Invalid username");
 49→
 50→  const res = await retryer(fetcher, { login: username });
 51→
 52→  if (res.data.errors) {
 53→    logger.error(res.data.errors);
 54→    throw Error(res.data.errors[0].message || "Could not fetch user");
 55→  }
 56→
 57→  let repoNodes = res.data.data.user.repositories.nodes;
 58→  let repoToHide = {};
 59→
 60→  // populate repoToHide map for quick lookup
 61→  // while filtering out
 62→  if (exclude_repo) {
 63→    exclude_repo.forEach((repoName) => {
 64→      repoToHide[repoName] = true;
 65→    });
 66→  }
 67→
 68→  // filter out repositories to be hidden
 69→  repoNodes = repoNodes
 70→    .sort((a, b) => b.size - a.size)
 71→    .filter((name) => {
 72→      return !repoToHide[name.name];
 73→    });
 74→
 75→  repoNodes = repoNodes
 76→    .filter((node) => {
 77→      return node.languages.edges.length > 0;
 78→    })
 79→    // flatten the list of language nodes
 80→    .reduce((acc, curr) => curr.languages.edges.concat(acc), [])
 81→    .reduce((acc, prev) => {
 82→      // get the size of the language (bytes)
 83→      let langSize = prev.size;
 84→
 85→      // if we already have the language in the accumulator
 86→      // & the current language name is same as previous name
 87→      // add the size to the language size.
 88→      if (acc[prev.node.name] && prev.node.name === acc[prev.node.name].name) {
 89→        langSize = prev.size + acc[prev.node.name].size;
 90→      }
 91→      return {
 92→        ...acc,
 93→        [prev.node.name]: {
 94→          name: prev.node.name,
 95→          color: prev.node.color,
 96→          size: langSize,
 97→        },
 98→      };
 99→    }, {});
100→
101→  const topLangs = Object.keys(repoNodes)
102→    .sort((a, b) => repoNodes[b].size - repoNodes[a].size)
103→    .reduce((result, key) => {
104→      result[key] = repoNodes[key];
105→      return result;
106→    }, {});
107→
108→  return topLangs;
109→}
110→
111→module.exports = fetchTopLanguages;
